# Test different transformations of the 4x4 pattern
import json

base = [
    [2, 2, 2, 2],
    [2, 0, 0, 0],
    [2, 0, 0, 2],
    [2, 0, 2, 2]
]

def rotate_90_clockwise(grid):
    return [list(row[::-1]) for row in zip(*grid)]

def rotate_90_counter_clockwise(grid):
    return [list(row) for row in zip(*grid[::-1])]

def flip_horizontal(grid):
    return [row[::-1] for row in grid]

def flip_vertical(grid):
    return grid[::-1]

print("Original:")
for row in base: print(row)

print("\nRotate 90° clockwise:")
for row in rotate_90_clockwise(base): print(row)

print("\nRotate 90° counter-clockwise:")
for row in rotate_90_counter_clockwise(base): print(row)

print("\nFlip horizontal:")
for row in flip_horizontal(base): print(row)

print("\nFlip vertical:")
for row in flip_vertical(base): print(row)

# The bottom-right area showed a pattern that looked like rotation!

